// Cada cluster de fuente única (source_count === 1) tiene exactamente un
// artículo en su array "articles". Aquí se aplana a la lista de artículos.
const items = $input.all();

return items.map(item => {
  const a = item.json.articles[0];
  return {
    json: {
      link: a.link,
      title: a.title,
      source_name: a.source_name,
      content: a.content || ''
    }
  };
});

// "Get Already-Processed Links" corre una sola vez (executeOnce) y devuelve
// un row por link ya resuelto con éxito (incluido o excluido, da igual).
// Aquí se recupera la lista real de artículos desde el nodo de extracción.
const processedLinks = new Set($input.all().map(item => item.json.link).filter(Boolean));
const articles = $('Extract Single Article').all().map(item => item.json);

const unprocessed = articles.filter(a => !processedLinks.has(a.link));

return unprocessed.map(a => ({ json: a }));

// Agrupa los artículos sin procesar en lotes de 8. Cada lote se manda al LLM
// en una sola llamada — con cientos de piezas de fuente única al día, una
// llamada por artículo agotaría el presupuesto diario de tokens (ver
// docs/06-quality-filter.md).
const BATCH_SIZE = 8;
const articles = $input.all().map(item => item.json);

const batches = [];
for (let i = 0; i < articles.length; i += BATCH_SIZE) {
  batches.push(articles.slice(i, i + BATCH_SIZE));
}

return batches.map(batch => ({ json: { articles: batch } }));

const MAX_CONTENT_CHARS = 1200;

const RULES = `Eres un editor de noticias. Vas a evaluar una lista de piezas de una sola fuente (sin otro medio que las corrobore todavía) y decidir cuáles merecen entrar en una sección secundaria de un briefing diario.

Para cada pieza, decide:
- "incluir": true si es un hecho noticioso sustancial (algo que pasó, con consecuencias o relevancia real) - false si es ruido: contenido de servicio/lifestyle (trucos, consejos, listas), rutina sin novedad real, o relleno promocional.
- "categoria": una de exactamente estas: internacional, economia, tecnologia, ciencia, espana, cultura, deportes, sociedad.
- "resumen_hechos": 1-2 frases, SOLO hechos verificables tal como los reporta esta fuente (recuerda que es la única fuente, no está corroborado por nadie más). Nada de interpretaciones, opiniones, ni valoraciones — ni tuyas ni citadas de la fuente. Si el texto es mayormente una cita/opinión de alguien sin hechos verificables detrás, "incluir": false.

No inventes ningún dato que no aparezca en el texto. Responde ÚNICAMENTE con un JSON: un array "articulos" con un objeto por artículo, en el mismo orden en que se dan, cada uno con "indice" (el número del artículo), "incluir", "categoria", "resumen_hechos" (resumen_hechos puede ser "" si incluir es false).`;

const items = $input.all();

return items.map(item => {
  const batch = item.json.articles;
  const blocks = batch.map((a, i) => `[${i}] Fuente: ${a.source_name}\nTítulo: ${a.title}\nTexto: ${(a.content || '').slice(0, MAX_CONTENT_CHARS)}`);
  const prompt = `${RULES}\n\nArtículos:\n\n${blocks.join('\n\n')}`;

  return {
    json: {
      articles: batch,
      prompt
    }
  };
});

function stripTrailingCommas(text) {
  return text.replace(/,(\s*[}\]])/g, '$1');
}

function extractJson(raw) {
  const withoutThink = raw.replace(/<think>[\s\S]*?<\/think>/i, '').trim();
  const cleaned = stripTrailingCommas(withoutThink);
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');
    if (start === -1 || end === -1 || end <= start) {
      throw new Error(`No se encontró un JSON válido en la respuesta del LLM. Respuesta cruda (primeros 500 caracteres): ${raw.slice(0, 500)}`);
    }
    const candidate = cleaned.slice(start, end + 1);
    try {
      return JSON.parse(candidate);
    } catch (e2) {
      throw new Error(`JSON extraído no parseable: ${e2.message}. Candidato (primeros 500 caracteres): ${candidate.slice(0, 500)}`);
    }
  }
}

const items = $input.all();
const output = [];

items.forEach((item, idx) => {
  // itemMatching resuelve el lote de origen real vía pairedItem, no por
  // posición dentro de esta rama (ver mismo problema ya resuelto en 05).
  const batchMeta = $('Build Prompt per Batch').itemMatching(idx).json;
  const batchArticles = batchMeta.articles;

  try {
    const raw = item.json.choices?.[0]?.message?.content;
    if (!raw) {
      throw new Error(`Respuesta de Groq sin contenido esperado. Payload recibido: ${JSON.stringify(item.json).slice(0, 500)}`);
    }
    const parsed = extractJson(raw);
    const results = parsed.articulos || parsed;
    if (!Array.isArray(results)) {
      throw new Error(`Se esperaba un array "articulos" en la respuesta. JSON recibido: ${JSON.stringify(parsed).slice(0, 500)}`);
    }

    batchArticles.forEach((article, i) => {
      const r = results.find(x => x.indice === i) || results[i];
      if (!r) {
        output.push({
          json: {
            link: article.link, title: article.title, source_name: article.source_name,
            categoria: null, incluir: false, resumen_hechos: null,
            status: 'error', error_message: `Sin resultado para el índice ${i} en la respuesta del lote`
          }
        });
        return;
      }
      output.push({
        json: {
          link: article.link,
          title: article.title,
          source_name: article.source_name,
          categoria: r.categoria || null,
          incluir: !!r.incluir,
          resumen_hechos: r.resumen_hechos || null,
          status: 'ok',
          error_message: null
        }
      });
    });
  } catch (e) {
    // Si el lote entero falla al parsear, se registran todos sus artículos
    // como error (reintetables en la próxima ejecución), sin perder el lote.
    batchArticles.forEach(article => {
      output.push({
        json: {
          link: article.link, title: article.title, source_name: article.source_name,
          categoria: null, incluir: false, resumen_hechos: null,
          status: 'error', error_message: e.message
        }
      });
    });
  }
});

return output;

// Rama de error de "Call Groq for Filtering" (onError: continueErrorOutput).
// Un lote entero que falla por red/timeout se registra como error por cada
// uno de sus artículos, para que se reintenten en la siguiente ejecución.
const items = $input.all();
const output = [];

items.forEach((item, idx) => {
  const batchMeta = $('Build Prompt per Batch').itemMatching(idx).json;
  const errorMessage =
    item.json?.error?.message ||
    item.json?.error ||
    item.json?.message ||
    `Fallo en la llamada a Groq sin mensaje de error legible: ${JSON.stringify(item.json).slice(0, 300)}`;

  batchMeta.articles.forEach(article => {
    output.push({
      json: {
        link: article.link,
        title: article.title,
        source_name: article.source_name,
        categoria: null,
        incluir: false,
        resumen_hechos: null,
        status: 'error',
        error_message: String(errorMessage).slice(0, 1000)
      }
    });
  });
});

return output;
